806.docs:
Gets XML version as typified enumeration.

According to the [grammar], the version *must* be the first thing in the declaration.
This method tries to extract the first thing in the declaration and return it.
In case of multiple attributes value of the first one is returned.

If version is missed in the declaration, or the first thing is not a version,
[`IllFormedError::MissingDeclVersion`] will be returned.

If version is not 1.0 or 1.1, [`IllFormedError::UnknownVersion`] will be returned.

# Examples

```
use quick_xml::XmlVersion;
use quick_xml::errors::{Error, IllFormedError};
use quick_xml::events::{BytesDecl, BytesStart};

// <?xml version='1.1'?>
let decl = BytesDecl::from_start(BytesStart::from_content(" version='1.1'", 0));
assert_eq!(decl.xml_version().unwrap(), XmlVersion::Explicit1_1);

// <?xml version='1.0' version='1.1'?>
let decl = BytesDecl::from_start(BytesStart::from_content(" version='1.0' version='1.1'", 0));
assert_eq!(decl.xml_version().unwrap(), XmlVersion::Explicit1_0);

// <?xml version='1.2'?>
let decl = BytesDecl::from_start(BytesStart::from_content(" version='1.2'", 0));
match decl.xml_version() {
    Err(Error::IllFormed(IllFormedError::UnknownVersion)) => {},
    _ => assert!(false),
}

// <?xml encoding='utf-8'?>
let decl = BytesDecl::from_start(BytesStart::from_content(" encoding='utf-8'", 0));
match decl.xml_version() {
    Err(Error::IllFormed(IllFormedError::MissingDeclVersion(Some(key)))) => assert_eq!(key, "encoding"),
    _ => assert!(false),
}

// <?xml encoding='utf-8' version='1.1'?>
let decl = BytesDecl::from_start(BytesStart::from_content(" encoding='utf-8' version='1.1'", 0));
match decl.xml_version() {
    Err(Error::IllFormed(IllFormedError::MissingDeclVersion(Some(key)))) => assert_eq!(key, "encoding"),
    _ => assert!(false),
}

// <?xml?>
let decl = BytesDecl::from_start(BytesStart::from_content("", 0));
match decl.xml_version() {
    Err(Error::IllFormed(IllFormedError::MissingDeclVersion(None))) => {},
    _ => assert!(false),
}
```

[grammar]: https://www.w3.org/TR/xml11/#NT-XMLDecl

1179.docs:
Reads the next event, borrow its content from the input buffer, and resolves
its namespace (if applicable).

Namespace is resolved only for [`Start`], [`Empty`] and [`End`] events.
For all other events the concept of namespace is not defined, so
a [`ResolveResult::Unbound`] is returned.

If you are not interested in namespaces, you can use [`read_event()`]
which will not automatically resolve namespaces for you.

There is no asynchronous `read_resolved_event_async()` version of this function,
because it is not necessary -- the contents are already in memory and no IO
is needed, therefore there is no potential for blocking.

# Examples

```
# use pretty_assertions::assert_eq;
use quick_xml::events::Event;
use quick_xml::name::{Namespace, QName, ResolveResult::*};
use quick_xml::reader::NsReader;

let mut reader = NsReader::from_str(r#"
    <x:tag1 xmlns:x="www.xxxx" xmlns:y="www.yyyy" att1 = "test">
       <y:tag2><!--Test comment-->Test</y:tag2>
       <y:tag2>Test 2</y:tag2>
    </x:tag1>
"#);
reader.config_mut().trim_text(true);

let mut count = 0;
let mut txt = Vec::new();
loop {
    match reader.read_resolved_event().unwrap() {
        (Bound(Namespace(b"www.xxxx")), Event::Start(e)) => {
            count += 1;
            assert_eq!(e.local_name(), QName(b"tag1").into());
        }
        (Bound(Namespace(b"www.yyyy")), Event::Start(e)) => {
            count += 1;
            assert_eq!(e.local_name(), QName(b"tag2").into());
        }
        (_, Event::Start(_)) => unreachable!(),

        (_, Event::Text(e)) => {
            txt.push(e.decode().unwrap().into_owned())
        }
        (_, Event::Eof) => break,
        _ => (),
    }
}
assert_eq!(count, 3);
assert_eq!(txt, vec!["Test".to_string(), "Test 2".to_string()]);
```

[`Start`]: Event::Start
[`Empty`]: Event::Empty
[`End`]: Event::End
[`read_event()`]: Self::read_event

1225.docs:
Returns all the bindings currently in effect except the default `xml` and `xmlns` bindings.

# Examples

This example shows what results the returned iterator would return after
reading each event of a simple XML.

```
# use pretty_assertions::assert_eq;
use quick_xml::name::{Namespace, PrefixDeclaration};
use quick_xml::NsReader;

let src = "<root>
  <a xmlns=\"a1\" xmlns:a=\"a2\">
    <b xmlns=\"b1\" xmlns:b=\"b2\">
      <c/>
    </b>
    <d/>
  </a>
</root>";
let mut reader = NsReader::from_str(src);
reader.config_mut().trim_text(true);
// No bindings at the beginning
assert_eq!(reader.resolver().bindings().collect::<Vec<_>>(), vec![]);

reader.read_resolved_event()?; // <root>
// No bindings declared on root
assert_eq!(reader.resolver().bindings().collect::<Vec<_>>(), vec![]);

reader.read_resolved_event()?; // <a>
// Two bindings declared on "a"
assert_eq!(reader.resolver().bindings().collect::<Vec<_>>(), vec![
    (PrefixDeclaration::Default, Namespace(b"a1")),
    (PrefixDeclaration::Named(b"a"), Namespace(b"a2"))
]);

reader.read_resolved_event()?; // <b>
// The default prefix got overridden and new "b" prefix
assert_eq!(reader.resolver().bindings().collect::<Vec<_>>(), vec![
    (PrefixDeclaration::Named(b"a"), Namespace(b"a2")),
    (PrefixDeclaration::Default, Namespace(b"b1")),
    (PrefixDeclaration::Named(b"b"), Namespace(b"b2"))
]);

reader.read_resolved_event()?; // <c/>
// Still the same
assert_eq!(reader.resolver().bindings().collect::<Vec<_>>(), vec![
    (PrefixDeclaration::Named(b"a"), Namespace(b"a2")),
    (PrefixDeclaration::Default, Namespace(b"b1")),
    (PrefixDeclaration::Named(b"b"), Namespace(b"b2"))
]);

reader.read_resolved_event()?; // </b>
// Still the same
assert_eq!(reader.resolver().bindings().collect::<Vec<_>>(), vec![
    (PrefixDeclaration::Named(b"a"), Namespace(b"a2")),
    (PrefixDeclaration::Default, Namespace(b"b1")),
    (PrefixDeclaration::Named(b"b"), Namespace(b"b2"))
]);

reader.read_resolved_event()?; // <d/>
// </b> got closed so back to the bindings declared on <a>
assert_eq!(reader.resolver().bindings().collect::<Vec<_>>(), vec![
    (PrefixDeclaration::Default, Namespace(b"a1")),
    (PrefixDeclaration::Named(b"a"), Namespace(b"a2"))
]);

reader.read_resolved_event()?; // </a>
// Still the same
assert_eq!(reader.resolver().bindings().collect::<Vec<_>>(), vec![
    (PrefixDeclaration::Default, Namespace(b"a1")),
    (PrefixDeclaration::Named(b"a"), Namespace(b"a2"))
]);

reader.read_resolved_event()?; // </root>
// <a> got closed
assert_eq!(reader.resolver().bindings().collect::<Vec<_>>(), vec![]);
# quick_xml::Result::Ok(())
```

